module top_module (
	input clk,
	input aresetn,
	input x,
	output reg z
);

localparam S = 2'b00, S1 = 2'b01, S10 = 2'b10;
reg [1:0] state, next_state;

always @(posedge clk or negedge aresetn) begin
    if (~aresetn) begin
        state <= S;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        S: begin
