            end else begin
                next_state = S1;
            end
            z = 0;
        end
        S1: begin
            if (x == 0) begin
                next_state = S10;
            end else begin
                next_state = S1;
            end
            z = 0;
        end
        S10: begin
            if (x == 0) begin
                next_state = S;
            end else begin
                next_state = S1;
            end
            z = x;
        end
        default: begin
            next_state = S;
            z = 0;
        end
    endcase
end

endmodule
